public int doubledSum(int a, int b) {
    java.util.concurrent.CompletableFuture<Integer> f = java.util.concurrent.CompletableFuture.supplyAsync(() -> a)
        .thenApply(x -> java.util.concurrent.CompletableFuture.supplyAsync(() -> x + b));
    return f.join() * 2;
}

